/**
 * Generates src/generated/plugins/ from the vendored Kong plugin JSON Schemas
 * (vendor/kong-schemas, see its SOURCE.md):
 *   json/<name>.ts  Kong's JSON Schema, unchanged (served at /schemas/plugins/{name})
 *   zod/zod.gen.ts  zod schemas, generated by @hey-api/openapi-ts's zod plugin
 *   index.ts        name → { json, zod } maps
 * and src/generated/deck.ts: decK's file schema (vendor/kong-schemas/deck),
 * unchanged, served as `@edgway/schema/deck` (the CLI's import-deck uses it).
 *
 * Usage: pnpm --filter @edgway/schema run codegen
 */
import {
  mkdirSync,
  readdirSync,
  readFileSync,
  rmSync,
  writeFileSync,
} from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { createClient } from "@hey-api/openapi-ts";

const pkg = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const source = path.resolve(pkg, "../../vendor/kong-schemas/3.9/plugins");
const out = path.join(pkg, "src/generated/plugins");
const banner = `// @generated by packages/schema/scripts/codegen-plugins.ts from vendor/kong-schemas/3.9/plugins. Do not edit.`;

const names = readdirSync(source)
  .filter((file) => file.endsWith(".json"))
  .map((file) => path.basename(file, ".json"))
  .sort();
const camel = (name: string) =>
  name.replace(/-([a-z])/g, (_, c: string) => c.toUpperCase());
const pascal = (name: string) =>
  camel(name).replace(/^[a-z]/, (c) => c.toUpperCase());
const read = (name: string) =>
  JSON.parse(readFileSync(path.join(source, `${name}.json`), "utf8"));

/**
 * Kong's plugin schemas omit `type: "object"` on their root node. Converters
 * treat an untyped node as "any", so add the implied type for zod only.
 */
const withRootType = (schema: Record<string, unknown>) =>
  "properties" in schema && !("type" in schema)
    ? { ...schema, type: "object" }
    : schema;

rmSync(out, { recursive: true, force: true });
mkdirSync(path.join(out, "json"), { recursive: true });

for (const name of names) {
  writeFileSync(
    path.join(out, "json", `${name}.ts`),
    `${banner}\nexport default ${JSON.stringify(read(name), null, 2)};\n`,
  );
}

await createClient({
  input: {
    openapi: "3.1.0",
    info: { title: "Kong plugin schemas", version: "3.9" },
    paths: {},
    components: {
      schemas: Object.fromEntries(
        names.map((name) => [pascal(name), withRootType(read(name))]),
      ),
    },
  },
  output: {
    path: path.join(out, "zod"),
    entryFile: false,
    // `.js` on relative imports: the built package is Node ESM.
    importFileExtension: ".js",
    header: [banner],
  },
  plugins: [{ name: "zod" }],
  logs: { level: "silent" },
});

writeFileSync(
  path.join(out, "index.ts"),
  [
    banner,
    ...names.map((name) => `import ${camel(name)} from "./json/${name}.js";`),
    `import * as zod from "./zod/zod.gen.js";`,
    "",
    "export const PLUGIN_JSON = {",
    ...names.map((name) => `  "${name}": ${camel(name)},`),
    "};",
    "",
    "export const PLUGIN_ZOD = {",
    ...names.map((name) => `  "${name}": zod.z${pascal(name)},`),
    "};",
    "",
  ].join("\n"),
);
const deck = path.resolve(
  pkg,
  "../../vendor/kong-schemas/deck/kong_json_schema.json",
);
writeFileSync(
  path.join(pkg, "src/generated/deck.ts"),
  `// @generated by packages/schema/scripts/codegen-plugins.ts from vendor/kong-schemas/deck. Do not edit.\n/** decK's file schema (draft-04), unchanged. */\nexport const deckFileSchema = ${JSON.stringify(JSON.parse(readFileSync(deck, "utf8")), null, 2)};\n`,
);
console.log(`codegen: ${names.length} plugin schemas, decK file schema`);
